import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import api from '../api/axios';
import styles from './BookingConfirmation.module.css';

export default function BookingConfirmation() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [booking, setBooking] = useState(null);

  useEffect(() => {
    api.get(`/bookings/${id}`).then(({ data }) => setBooking(data)).catch(console.error);
  }, [id]);

  if (!booking) return <p className={styles.loading}>Loading...</p>;

  const movie = booking.showtime?.movie;
  const showtime = booking.showtime;

  return (
    <div className={styles.container}>
      <div className={styles.card}>
        <div className={styles.checkmark}>✅</div>
        <h2>Booking Confirmed!</h2>
        <p className={styles.bookingId}>Booking ID: <strong>{booking._id}</strong></p>
        {booking.paymentId && <p className={styles.txn}>Transaction: {booking.paymentId}</p>}

        <div className={styles.details}>
          <div className={styles.row}><span>Movie</span><span>{movie?.title}</span></div>
          <div className={styles.row}><span>Theater</span><span>{showtime?.theater} — {showtime?.screen}</span></div>
          <div className={styles.row}><span>Date</span><span>{showtime?.date}</span></div>
          <div className={styles.row}><span>Time</span><span>{showtime?.startTime}</span></div>
          <div className={styles.row}><span>Seats</span><span>{booking.seats.map((s) => s.seatNumber).join(', ')}</span></div>
          <div className={styles.row}><span>Total Paid</span><span>₹{booking.totalAmount}</span></div>
        </div>

        <div className={styles.qr}>🎟️ Show this at the counter</div>

        <div className={styles.actions}>
          <button className={styles.btn} onClick={() => navigate('/bookings')}>My Bookings</button>
          <button className={styles.outline} onClick={() => navigate('/')}>Browse More</button>
        </div>
      </div>
    </div>
  );
}
